			AuthorEmail: "test@test.com", IsFirstCheckpoint: false,
		}); err != nil {
			t.Fatalf("WriteTemporary code changes error: %v", err)
		}
	}

	writeCheckpoints(sessionIDLocal, "")               // Main worktree (matches test env)
